import re
SP = r"C:\wt\logos-t423-m8-fable\.ai\scratch\multi_model_bible_chunking\M8_fable\sp_durable"
o = {}
for l in open(SP + r"\Dan\Dan_oshb.txt", "rb").read().decode("utf-8").split("\n"):
    if "\t" in l:
        k, t = l.split("\t", 1); o[k] = t.split(" ")
def sk(w): return "".join(c for c in w if "\u05d0" <= c <= "\u05ea")
a = [sk(w) for w in o["Dan.3.5"][4:10]]; b = [sk(w) for w in o["Dan.3.7"][10:15]]
print("oshb 3:5 words 5-10:", len(a), a)
